return items.map(item => {
  const rawEmail = item.json.Email;
  const linkedinUrl = item.json.LinkedinUrl;

  let email = '';
  let email2 = '';

  try {
    // Try parsing the email field if it's a stringified array
    const parsed = JSON.parse(rawEmail);

    if (Array.isArray(parsed)) {
      email = parsed[0] || '';
      email2 = parsed[1] || '';
    } else {
      email = parsed || '';
    }
  } catch (e) {
    // If not JSON format, assume it's a plain string
    email = rawEmail || '';
  }

  return {
    json: {
      email,
      email2,
      linkedinUrl
    }
  };
});
